    local isBig = checkNumber(self._curType) == Type.big
    CfUtils.SetActive(self.EndingGroup1, isBig)
    CfUtils.SetActive(self.EndingGroup2, not isBig)

    if isBig then
        self:FillBig()
    else
        self:FillSmall()
    end
end

function UIPolePlotCGEndingDialog:FillBig()
    local vo = QuestConfMgr:GetInstance():GetQuestVoById(self._data.chapterId)

    if vo then
        vo = QuestConfMgr:GetInstance():GetRoleStoryChapterVo(vo.stageID)
        if vo then
            CfUtils.FillText(self.TxtTitle, vo.roleName) 
        end
    end

    CfUtils.FillImage(self.ImgRoleCG, self._data.cg)

    if checkString(self._data.text) ~= "" then
        CfUtils.SetActive(self.EndingGroup1.transform:Find("DescGroup"), true)
    end
    CfUtils.FillText(self.EndingGroup1.transform:Find("DescGroup/TxtTitle"), self._data.text)
end

